#include <stdio.h>

int main(void) {
    long long n;
    scanf("%lld", &n);
    int prime = n >= 2;
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            prime = 0;
            break;
        }
    }
    printf("%s\n", prime ? "да" : "нет");
    return 0;
}

