#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    long long sum = 0;
    int skipped = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x % 3 == 0) {
            skipped++;
            continue;
        }
        sum += x;
    }
    printf("%lld %d\n", sum, skipped);
    return 0;
}

