#include <stdio.h>

int main(void) {
    long long limit;
    int n;
    scanf("%lld %d", &limit, &n);
    long long total = 0;
    int loaded = 0;
    for (int i = 0; i < n; i++) {
        long long w;
        scanf("%lld", &w);
        if (total + w > limit) {
            break;
        }
        total += w;
        loaded++;
    }
    printf("%d %lld\n", loaded, total);
    return 0;
}

